import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import { useNavigate } from "react-router-dom";
import "../App.css";
import API_BASE_URL from "../config";

const AllListings = () => {
  const navigate = useNavigate();
  const userId = sessionStorage.getItem("userId");
  const [listings, setListings] = useState([]);

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/listings`)
      .then((res) => res.json())
      .then((data) => {
        const otherListings = data.filter((item) => String(item.user_id) !== String(userId));
        setListings(otherListings);
      })
      .catch((err) => console.error("Error fetching listings:", err));
  }, [userId]);

  const handleBuy = async (item) => {
    try {
      const response = await fetch(`${API_BASE_URL}/api/cart/add`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          user_id: userId,
          listing_id: item.id
        })
      });

      if (response.ok) {
        alert("Added to cart!");
      } else {
        const error = await response.text();
        alert("Failed to add to cart: " + error);
      }
    } catch (err) {
      console.error("Buy error:", err);
      alert("Something went wrong.");
    }
  };

  return (
    <div className="dashboard-wrapper">
      <Navbar />
      <main className="dashboard-main">
        <h2 style={{ textAlign: "center", marginBottom: "32px" }}>Explore All Listings</h2>

        <div className="item-grid">
          {listings.length > 0 ? (
            listings.map((item) => (
              <div className="item-card" key={item.id}>
                <div className="cart-item-top">
                  <div className="cart-item-image">
                    {item.image ? <img src={item.image} alt={item.title} /> : <span>No Image</span>}
                  </div>
                  <div className="cart-item-info">
                    <h4>{item.title}</h4>
                    <p>{item.description}</p>
                    <p><strong>Condition:</strong> {item.condition}</p>
                    <p><strong>Price:</strong> ${parseFloat(item.price).toFixed(2)}</p>
                  </div>
                </div>
                <div className="cart-item-actions">
                  <button className="buy-btn" onClick={() => handleBuy(item)}>Buy</button>
                </div>
              </div>
            ))
          ) : (
            <p style={{ textAlign: "center" }}>No listings available from other users.</p>
          )}
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default AllListings;
